ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_misc_1"] = {
{"fw_ld4_topics_a_0001","after_fight",2,"reg=civilian,family,worker,rescue",{1,"Shit- shit shit shit, did you see that?",2,"I saw it, I saw it, breathe",1,"It was RIGHT there, it was right on top of me",2,"I know, I know, you're okay, look at me, you're okay",1,"I'm- I'm not okay, my hands, look at my hands",2,"Sit down, put your head between your knees"}},
{"fw_ld4_topics_a_0002","after_fight",2,"reg=civilian,family,worker,rescue",{1,"Is everyone alright?",2,"I think so, I'm bleeding, but it's not mine",1,"Whose is it?",2,"Don't ask, please don't ask",1,"...okay, I won't, sit with me"}},
{"fw_ld4_topics_a_0003","after_fight",2,"reg=civilian,family,worker,rescue",{1,"I killed it",2,"You did",1,"It had a face, it had a FACE, it looked like Mr. Willis",2,"It wasn't Mr. Willis anymore, you know that",1,"Tell me again",2,"It wasn't him, it wasn't him, it wasn't him"}},
{"fw_ld4_topics_a_0004","after_fight",2,"reg=civilian,family,worker,rescue",{1,"Anybody bit?",2,"No",1,"Show me your arms",2,"Why do you-",1,"SHOW ME YOUR ARMS",2,"Jeez- here, see? Nothing there, relax"}},
{"fw_ld4_topics_a_0005","after_fight",2,"reg=civilian,family,worker,rescue",{1,"We did it",2,"We did it",1,"We did it!!",2,"Don't cheer, they might hear",1,"Sorry- I'm cheering quietly, yay... quietly"}},
{"fw_ld4_topics_a_0006","after_fight",2,"reg=civilian,family,worker,rescue",{1,"I can't stop laughing",2,"It's the adrenaline",1,"I know, but it's not even funny",2,"I know, it's not, but you're alive, let it out",1,"Hahaha... ha... oh God, I'm crying now"}},
{"fw_ld4_topics_a_0007","after_fight",2,"reg=civilian,family,worker,rescue",{1,"My leg's shaking so hard I can't stand",2,"Sit, sit, I've got you",1,"I thought that was it, I really thought that was it",2,"It wasn't, it wasn't, drink some water"}},
{"fw_ld4_topics_a_0008","after_fight",2,"reg=civilian,family,worker,rescue",{1,"You were incredible",2,"I was terrified",1,"You didn't look terrified",2,"I was, I was trying not to throw up"}},
{"fw_ld4_topics_a_0009","after_fight",2,"reg=civilian,family,worker,rescue",{1,"I froze",2,"We all do",1,"I could've gotten you killed",2,"But you didn't, and we're both still here, so stop",1,"Thank you for not hating me"}},
{"fw_ld4_topics_a_0010","after_fight",2,"reg=civilian,family,worker,rescue",{1,"Where's Danny?",2,"Look at me",1,"Where's DANNY?",2,"He didn't make it, I'm sorry, I'm so sorry",1,"No- no, I just saw him, he was right there!"}},
{"fw_ld4_topics_a_0011","after_fight",2,"reg=law,swat",{1,"Status",2,"Two wounded, no fatalities",1,"Thank God",2,"Reyes took a bite on the forearm",1,"...how bad?",2,"Bad enough that he asked me to do it, and I did"}},
{"fw_ld4_topics_a_0012","after_fight",2,"reg=law,swat",{1,"You alright, partner?",2,"Ask me tomorrow",1,"Right, that makes sense",2,"Hey, thanks for the cover back there",1,"Always"}},
{"fw_ld4_topics_a_0013","after_fight",2,"reg=law,swat",{1,"How many rounds do you have left?",2,"Six",1,"I've got four",2,"Then we're not fighting anything else today",1,"That's the plan"}},
{"fw_ld4_topics_a_0014","after_fight",2,"reg=law,swat",{1,"Report the incident",2,"To who?",1,"To me, I'll write it down, so it exists",2,"Fifteen infected, one civilian lost, two officers wounded",1,"Noted"}},
{"fw_ld4_topics_a_0015","after_fight",2,"reg=military,elite",{1,"Cease fire, cease fire",2,"Clear",1,"Sound off",2,"Alpha, Bravo, Charlie, Delta",1,"Anyone hurt?",2,"Just my pride, Sergeant"}},
{"fw_ld4_topics_a_0016","after_fight",2,"reg=military,elite",{1,"Corporal, you did well",2,"Thank you, Sergeant",1,"Don't thank me, thank the training",2,"And the luck",1,"And the luck"}},
{"fw_ld4_topics_a_0017","after_fight",2,"reg=military,elite",{1,"Check your gear",2,"Done",1,"Count ammunition",2,"Four mags, half a mag, a bad attitude",1,"Same here"}},
{"fw_ld4_topics_a_0018","after_fight",2,"reg=military,elite",{1,"First time?",2,"Yes, Sergeant",1,"How do you feel?",2,"Sick",1,"That's right, if you didn't, I'd worry",2,"Does it get easier?",1,"It gets quieter, which is different"}},
{"fw_ld4_topics_a_0019","after_fight",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Ha ha ha, did you see his face?!",2,"Which one?",1,"Any of them, they were terrified, then they were dead",2,"You're sick",1,"I'm alive, you're the one who's sick"}},
{"fw_ld4_topics_a_0020","after_fight",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Anyone hurt?",2,"Tommy's bleeding",1,"Tommy's always bleeding",2,"This time it's real bleeding",1,"Shit, tie it off, tie it off"}},
{"fw_ld4_topics_a_0021","after_fight",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"We should celebrate",2,"With what?",1,"The warm beer in my pack",2,"Pass it over, I'll drink to the dead"}},
{"fw_ld4_topics_a_0022","after_fight",2,"reg=family",{1,"Children, come here, come here, are you hurt?",2,"No, Mama",1,"Let me look, let me look at you all",2,"We're fine, Mama, really",1,"Thank God, thank God, thank God"}},
{"s10_after_driving_teacher_001","after_fight",2,"reg=civilian,family|tmp=fresh|day=1,60|mood=sad",{1,"My hands won't quit shaking",2,"Sit on 'em a minute",1,"That was Mr. Ogden, he taught me driver's ed - made me parallel park nine times",2,"He was gone before you ever swung - sit on your hands"}},
{"s10_after_ace_canteen_002","after_fight",2,"reg=military|tmp=seasoned,veteran|mood=grim",{1,"Ammo, casualties, equipment - go",2,"Two mags a man, Sergeant - no casualties, lost one canteen",1,"Whose canteen?",2,"Mine, it's still hooked on one of them"}},
{"s10_after_eyes_shut_tire_003","after_fight",3,"reg=raider|tmp=predator|mood=funny|world=vehicle",{1,"You see me? You see me knock that fella off the tailgate?",2,"I saw you shut both eyes and pull",1,"And it worked!",3,"Worked on the back tire, truck's sitting on the rim now"}},
{"s10_after_back_of_hand_004","after_fight",2,"reg=law|day=3,200|mood=sad",{1,"I need to write this up",2,"Write it up for who?",1,"Discharge of a firearm - two rounds - subject armed, it has to be written down someplace",2,"Write it on the back of my hand, then, if that helps"}},
{"s10_after_eleven_times_005","after_fight",2,"reg=family|role=family_youth,family_woman,family_man|mood=sad",{1,"You did good with the bat",2,"I hit it eleven times",1,"Once would've done it",2,"I know, I couldn't stop counting"}},
{"s10_after_buzz_quieter_006","after_fight",2,"reg=gang,crime|mood=fear|world=door,stairs",{1,"Hahaha! Man, did you see it when the door came off the hinges?",2,"Calm down",1,"I can't calm down, my whole body's buzzing!",2,"Then buzz quieter, there's more of 'em on the stairs"}},
{"s10_after_leather_in_july_007","after_fight",2,"reg=club|mood=fear|world=summer",{1,"Took a chunk right out of my leathers",2,"Skin?",1,"Why you think I wear leather in summer, brother? Skin's fine",2,"Roll it up and show me anyway"}},
{"s10_after_hot_wash_008","after_fight",3,"reg=elite|tmp=veteran|mood=calm|world=door,stairs",{1,"Hot wash, what went wrong",2,"Stairwell, I was slow on the door",3,"I crossed his line on the landing",1,"Both fixed next time, what went right",2,"Everybody's sitting here"}},
{"s10_after_dont_like_you_009","after_fight",2,"reg=prison|mood=warm",{1,"You pulled me out of that motel room",2,"Yep",1,"You don't even like me",2,"Don't like you now, either, put your shoe back on"}},
{"s10_after_bent_shovel_010","after_fight",2,"reg=worker,civilian,family|tmp=seasoned|mood=sad",{1,"Bent my good shovel on that last one",2,"Better the shovel than you",1,"Daddy dug his garden with this shovel thirty years, never once bent it",2,"He never had to use it for this"}},
{"s10_after_laundry_not_medicine_011","after_fight",2,"reg=rescue|mood=funny",{1,"Anybody bit, scratched, or bled on? Hands up",2,"I got bled on",1,"Where? Mouth, eyes, an open cut?",2,"On my new shirt",1,"That's laundry, that's not medicine"}},
{"s10_after_same_patch_012","after_fight",2,"reg=military|role=soldier_green,soldier_nco,soldier|day=3,200|mood=grim",{1,"Sergeant, that one was wearing Guard fatigues",2,"I saw it",1,"Same shoulder patch as ours",2,"Pick up your brass, Private - every piece - count it out loud for me"}},
{"s10_after_stayed_in_irvington_013","after_fight",2,"reg=raider,outlaw|tmp=predator|mood=grim",{1,"Should've stayed in Irvington, Boyd",2,"He can't hear you",1,"I know, that's how come I can say it"}},
{"s10_after_just_tell_her_six_014","after_fight",2,"reg=civilian,family,worker|tmp=seasoned|day=10,300|mood=sad",{1,"Six, out by the pump house",2,"Any we knew?",1,"One, the Arnett girl's husband, still had his ring on",2,"You taking it to her?",1,"Not today, today I'm just gonna tell her six"}},
{"s10_after_dont_tell_mama_015","after_fight",3,"reg=family,civilian|role=family_youth,civilian_man,civilian_woman|tmp=fresh|mood=funny|world=door",{1,"I got to tell y'all something",2,"You're bit?",1,"No, I peed a little, when it grabbed the screen door",3,"Me too - don't tell Mama"}},
{"s10_after_finger_moving_016","after_fight",2,"reg=swat,law|tmp=seasoned,veteran|mood=grim|world=vehicle,building",{1,"Closet in the back bedroom, there was a man in it - alive",2,"You didn't fire",1,"I almost did, my finger was already moving",2,"But it didn't - go sit on the tailgate a minute"}},
{"s10_after_ten_gauge_order_017","after_fight",2,"reg=outlaw,family|mood=funny|world=building",{1,"Granddaddy's ten-gauge knocked me clean off the porch",2,"You hit anything?",1,"Porch roof, the swing, then one of them"}},
{"s10_after_burn_detail_upwind_018","after_fight",2,"reg=military,law|tmp=veteran,seasoned|day=5,300|mood=grim|world=vehicle,wind",{1,"Burn detail at sixteen hundred, diesel and the bald tires",2,"Upwind of the chow line this time?",1,"Upwind of everything, I learned my lesson"}},
{"s10_after_graze_in_side_019","after_fight",2,"reg=gang,crime,club|mood=fear",{1,"It's a graze - it's nothing",2,"It's in your side, man",1,"It's a graze, in my side",2,"Lay down before you fall down"}},
{"s10_after_cracked_handle_020","after_fight",1,"reg=civilian,worker,outlaw,family|tmp=seasoned|hour=16,5|mood=calm",{1,"Handle's cracked, you held, though",1,"Tape tonight, maybe a new handle off that old rake by the shed",1,"You and me did alright today"}},
{"s10_after_me_and_bobby_021","after_fight",3,"reg=civilian,family|tmp=fresh|mood=angry|world=door",{1,"You ran",2,"I went for help",1,"There's no help! There was me and Bobby and a screen door!",3,"Stop, both of you stop - Bobby's fine, everybody's still here"}},
{"s10_after_axe_stranger_022","after_fight",2,"reg=civilian,family,worker|mood=warm|world=fence,road",{1,"Who was that fella? The one with the axe?",2,"Never laid eyes on him before",1,"Came over the fence, cleared the whole yard, and just walked on up the road",2,"Didn't stop for water or nothing, I hollered after him"}},
}
